const progress=document.querySelector('#progressBar');addEventListener('scroll',()=>{const h=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${h?scrollY/h*100:0}%`});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.14});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));let units=0;const output=document.querySelector('#units'),monthly=document.querySelector('#monthly'),selection=document.querySelector('#selection');function update(){output.textContent=units;monthly.textContent=(8400+units*1000).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});const selected=[...document.querySelectorAll('.addon[aria-pressed=true]')].map(x=>x.dataset.name);selection.textContent=selected.length?`Produtos para cotar: ${selected.join(', ')}.`:'Sem produtos adicionais selecionados.'}document.querySelector('#plus').onclick=()=>{units++;update()};document.querySelector('#minus').onclick=()=>{units=Math.max(0,units-1);update()};document.querySelectorAll('.addon').forEach(btn=>btn.onclick=()=>{const active=btn.getAttribute('aria-pressed')==='true';btn.setAttribute('aria-pressed',String(!active));btn.querySelector('i').textContent=active?'+':'✓';update()});update();
